css:
/* Kraken Kinetic (origin/dev): Obsidian frame + one lit sheet + Peek Flow AI halo */
:root {
  --kraken-display: "Bricolage Grotesque Variable", "Bricolage Grotesque", "Source Sans 3", ui-sans-serif, system-ui, sans-serif;
  --kraken-sans: "Source Sans 3", ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --kraken-halo: linear-gradient(90deg, #f33c9f, #f73cdc, #ad37f8, #5e4afb, #3388fe, #0bb7f5, #00d4c9, #02c49c);
  font-variant-numeric: tabular-nums;
}

body {
  font-family: var(--kraken-sans);
}

h1, h2, h3, [data-chat-header] {
  font-family: var(--kraken-display);
  letter-spacing: -0.02em;
}

/* Obsidian navigation rail with Kraken's drifting violet glow */
[data-slot="sidebar-inner"] {
  position: relative;
  background-color: #07080C !important;
  background-image: radial-gradient(120% 55% at 50% 108%, rgb(91 61 245 / 0.22), transparent 72%) !important;
}

/* Thread rows: 10px corners, crisp white-wash active pill with 3px left bar */
[data-thread-item] {
  position: relative;
  border-radius: 10px !important;
  transition: background-color 150ms cubic-bezier(0.23, 1, 0.32, 1), color 150ms cubic-bezier(0.23, 1, 0.32, 1);
}

[data-thread-item][data-active="true"],
[data-thread-item][data-selected="true"],
[data-thread-item][aria-current="page"] {
  background: rgb(255 255 255 / 0.12) !important;
  box-shadow: inset 0 0 0 1px rgb(255 255 255 / 0.16);
}

[data-thread-item][data-active="true"]::before,
[data-thread-item][data-selected="true"]::before,
[data-thread-item][aria-current="page"]::before {
  content: "";
  position: absolute;
  left: 0;
  top: 22%;
  bottom: 22%;
  width: 3px;
  border-radius: 3px;
  background: #8B74FF;
}

[data-slot="project-monogram"] {
  border-radius: 8px;
}

/* Frosted sticky header over the lit sheet */
:root:not(.dark) [data-chat-header] {
  background: color-mix(in srgb, #FFFFFF 86%, transparent) !important;
  backdrop-filter: blur(12px);
  border-bottom: 1px solid #ECEEF2 !important;
}

.dark [data-chat-header] {
  background: color-mix(in srgb, #101218 86%, transparent) !important;
  backdrop-filter: blur(12px);
  border-bottom: 1px solid #282C36 !important;
}

/* Lit sheet conversation area */
:root:not(.dark) [data-workspace-area="conversation"] {
  background: #FFFFFF;
}

.dark [data-workspace-area="conversation"] {
  background: #101218;
}

/* User message bubble: tonal inset surface with Kinetic hairline */
:root:not(.dark) [data-user-message-bubble] {
  background: #F1F3F6 !important;
  border: 1px solid #E2E5EC;
  border-radius: 12px !important;
}

.dark [data-user-message-bubble] {
  background: #191C24 !important;
  border: 1px solid #282C36;
  border-radius: 12px !important;
}

/* Code blocks */
:root:not(.dark) .chat-markdown-codeblock {
  border-radius: 12px !important;
  border: 1px solid #E2E5EC !important;
  background: #F7F8FA !important;
}

.dark .chat-markdown-codeblock {
  border-radius: 12px !important;
  border: 1px solid #282C36 !important;
  background: #090A0F !important;
}

/* Composer card with Kraken's Peek Flow AI spectral edge on focus */
[data-slot="composer-host"] {
  position: relative;
  border-radius: 14px !important;
  transition: border-color 160ms ease, box-shadow 200ms cubic-bezier(0.23, 1, 0.32, 1);
}

:root:not(.dark) [data-slot="composer-host"] {
  background: #FFFFFF !important;
  border: 1px solid #DDE0E7 !important;
  box-shadow: 0 1px 3px rgb(7 8 12 / 0.06), 0 10px 24px -10px rgb(7 8 12 / 0.14) !important;
}

.dark [data-slot="composer-host"] {
  background: #161820 !important;
  border: 1px solid #282C36 !important;
  box-shadow: 0 1px 3px rgb(0 0 0 / 0.45), 0 14px 30px -12px rgb(0 0 0 / 0.75) !important;
}

[data-slot="composer-host"]:focus-within {
  border-color: transparent !important;
  background-image: linear-gradient(var(--composer-bg, #FFFFFF), var(--composer-bg, #FFFFFF)), var(--kraken-halo) !important;
  background-origin: border-box !important;
  background-clip: padding-box, border-box !important;
}

:root:not(.dark) [data-slot="composer-host"]:focus-within {
  --composer-bg: #FFFFFF;
  box-shadow: 0 0 0 3px rgb(91 61 245 / 0.12), 0 14px 30px -12px rgb(7 8 12 / 0.18) !important;
}

.dark [data-slot="composer-host"]:focus-within {
  --composer-bg: #161820;
  box-shadow: 0 0 0 3px rgb(139 116 255 / 0.16), 0 16px 34px -12px rgb(0 0 0 / 0.85) !important;
}

/* Kinetic card & overlay depth */
[data-thread-details-card] {
  border-radius: 12px !important;
}

:root:not(.dark) [data-slot="dialog-popup"],
:root:not(.dark) [data-slot="popover-popup"],
:root:not(.dark) [data-slot="menu-popup"] {
  border-radius: 14px !important;
  box-shadow: 0 0 0 1px rgb(10 12 16 / 0.06), 0 18px 50px -16px rgb(10 12 16 / 0.28) !important;
}

.dark [data-slot="dialog-popup"],
.dark [data-slot="popover-popup"],
:root.dark [data-slot="menu-popup"] {
  border-radius: 14px !important;
  box-shadow: 0 0 0 1px rgb(255 255 255 / 0.08), 0 18px 56px -16px rgb(0 0 0 / 0.82) !important;
}

/* Slim Kraken scrollbars */
[data-slot="scroll-area-thumb"],
::-webkit-scrollbar-thumb {
  border-radius: 999px;
}
